const fs = require('fs');
const tokens = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = tokens[0];
const a = tokens.slice(1, n + 1);

// A altura final ótima é H = max(a). Cada operação eleva um intervalo de valor
// v para v+1 ("operação de nível v"). Um prédio i só pode participar de uma
// operação de nível v se a[i] <= v (sua altura nunca fica abaixo da inicial).
// Logo, para cada nível v (1 <= v < H), as operações de nível v devem cobrir
// exatamente o conjunto S_v = {i : a[i] <= v}, e cada operação está contida em
// um único bloco maximal de S_v (prédios separados por alguém com a[i] > v
// nunca podem estar juntos numa operação, pois esse vizinho nunca terá valor v).
// Portanto o nº de operações de nível v é >= número de blocos maximais de S_v,
// e esse limite é atingível executando todas as operações nível a nível
// crescente (cada bloco maximal de S_v está todo com valor exatamente v).
//
// Resposta = soma sobre v de (#blocos maximais de {i : a[i] <= v})
//          = (max - a[0]) + soma de max(0, a[i-1] - a[i]) para i >= 1.
//   (o prédio 1 inicia um bloco em todo nível v com a[0] <= v <= max-1;
//    o prédio i (i>=1) inicia um bloco no nível v para a[i] <= v < a[i-1])

const mx = Math.max(...a);
let ans = mx - a[0];
for (let i = 1; i < n; i++) {
  if (a[i - 1] > a[i]) ans += a[i - 1] - a[i];
}

console.log(ans);
